import java.util.*;

class Solution {
  private final Map<String, String> parent = new HashMap<>();
  private final Map<String, Double> weight = new HashMap<>(); // value(node) / value(parent)

  public double[] calcEquation(List<List<String>> equations, double[] values, List<List<String>> queries) {
    for (int i = 0; i < equations.size(); i++) {
      String a = equations.get(i).get(0), b = equations.get(i).get(1);
      add(a);
      add(b);
      String ra = find(a), rb = find(b);
      if (!ra.equals(rb)) {
        // a = w_a * ra, b = w_b * rb, a / b = values[i]  =>  ra = values[i] * w_b / w_a * rb
        parent.put(ra, rb);
        weight.put(ra, values[i] * weight.get(b) / weight.get(a));
      }
    }
    double[] ans = new double[queries.size()];
    for (int i = 0; i < queries.size(); i++) {
      String a = queries.get(i).get(0), b = queries.get(i).get(1);
      if (!parent.containsKey(a) || !parent.containsKey(b) || !find(a).equals(find(b))) ans[i] = -1.0;
      else ans[i] = weight.get(a) / weight.get(b);
    }
    return ans;
  }

  private void add(String x) {
    if (!parent.containsKey(x)) {
      parent.put(x, x);
      weight.put(x, 1.0);
    }
  }

  private String find(String x) {
    String p = parent.get(x);
    if (!p.equals(x)) {
      String root = find(p);
      weight.put(x, weight.get(x) * weight.get(p));
      parent.put(x, root);
    }
    return parent.get(x);
  }
}
